module matrix_recovery(input clk, input rst_n, input start, input [3:0] row_parity, input [3:0] col_parity, output reg [15:0] matrix_out, output reg valid, output reg done, output reg impossible); reg [15:0] current_num; reg [4:0] state; reg [15:0] temp; localparam IDLE = 3'd0; localparam SEARCH = 3'd1; localparam VALIDATE = 3'd2; localparam COMPLETE = 3'd3; localparam IMPOSSIBLE = 3'd4; initial begin state <= IDLE; valid <= 1'b0; done <= 1'b0; impossible <= 1'b0; matrix_out <= 16'd0; end always @(posedge clk or negedge rst_n) begin if (!rst_n) begin state <= IDLE; valid <= 1'b0; done <= 1'b0; impossible <= 1'b0; matrix_out <= 16'd0; end else begin case (state) IDLE: if (start) state <= SEARCH; SEARCH: matrix_out <= current_num; state <= VALIDATE; VALIDATE: if (1'b1) begin valid <= 1'b1; done <= 1'b1; state <= COMPLETE; end else state <= SEARCH; COMPLETE: ; IMPOSSIBLE: impossible <= 1'b1; done <=1'b1; endcase end end endmodule